{
  "title": "Belém to Bairro Alto, close and cosy",
  "summary": "A slower Tuesday that keeps Belém Tower as the anchor, then wanders through nearby flavours, a tram ride, and finishes with Bairro Alto's evening glow.",
  "stops": [
    {
      "poi_id": "p1",
      "kind": "activity",
      "must_do_id": "m1",
      "note": "The one stop the crew would never forgive me for dropping. Belém Tower, looking all dramatic by the water, history with a side of sea breeze."
    },
    {
      "poi_id": "p14",
      "kind": "meal",
      "must_do_id": null,
      "note": "Lunch right by the tower, because walking far on an empty stomach is a crime. Pastéis de Belém keeps the vegetarians happy and the rest of us grinning."
    },
    {
      "poi_id": "p10",
      "kind": "activity",
      "must_do_id": null,
      "note": "A tram ride that rattles and rolls through the city without asking anyone to hike across half of Lisbon. Photo spots appear at every bend, no long ride needed."
    },
    {
      "poi_id": "p12",
      "kind": "activity",
      "must_do_id": null,
      "note": "Feira da Ladra is close to the tram's wanderings and full of local life. A flea market where the treasure is the people-watching, not the walking distance."
    },
    {
      "poi_id": "p16",
      "kind": "meal",
      "must_do_id": null,
      "note": "Dinner at Ao 26 Vegan Food Project, because every meal must suit the vegetarians and this place does it with proper Lisbon warmth. Grilled sardines can wait for another day."
    },
    {
      "poi_id": "p11",
      "kind": "activity",
      "must_do_id": null,
      "note": "Bairro Alto wakes up late, so we end the day here. Cobbled lanes, tiny bars, and the night owls finally get their moment without a single long ride."
    }
  ]
}
